memo = {}

def S(n):
  if n in memo:
    return memo[n]
  if n == 1:
    ret = [1]
  else:
    ret = S(n - 1) + [n] + S(n - 1)
  memo[n] = ret
  return ret


N = int(input())
print(*S(N))

from functools import lru_cache

@lru_cache(maxsize=None)
def S(n):
  if n == 1:
    return [1]
  else:
    return S(n - 1) + [n] + S(n - 1)


N = int(input())
print(*S(N))

